// notable_intensity_notes has two shapes: flat {unit, note} entries and highest_single_regiment_rate, which nests
// {union:{unit,rate,note}, confederate:{...}}. Every entry becomes a titled card; a raw key or "undefined" never prints.
const NOTE_TITLES = {
  most_compressed_union: 'Most compressed fight, Union',
  most_compressed_confederate: 'Most intense half hour, Confederate',
  longest_sustained_action: 'Longest sustained fight',
  highest_single_regiment_rate: 'Highest regimental loss rate',
};
const tidy = s => String(s).replace(/ -- /g, ' \u2014 ');
const groupName = u => { const m = /\(([^)]+)\)/.exec(String(u || '')); return m ? m[1] : String(u || ''); };
const notes = data.notable_intensity_notes || {};
for (const key of Object.keys(notes)) {
  const n = notes[key];
  const title = NOTE_TITLES[key] || key.replace(/_/g, ' ').replace(/^./, ch => ch.toUpperCase());
  if (n && typeof n.note === 'string') {
    cards.push({ num: groupName(n.unit), lbl: title, note: tidy(n.note) });
  } else if (n && typeof n === 'object') {
    for (const side of ['union', 'confederate']) {
      const s = n[side];
      if (s && typeof s.note === 'string') {
        cards.push({ num: typeof s.rate === 'number' ? s.rate + '%' : groupName(s.unit), lbl: title + ', ' + (side === 'union' ? 'Union' : 'Confederate'), note: tidy(s.note) });
      }
    }
  }
}
cards.forEach(c => {
  const card = document.createElement('div');
  card.className = 'stat-card';
  [['num', c.num], ['lbl', c.lbl], ['note', c.note]].forEach(([cls, text]) => {
    const d = document.createElement('div');
    d.className = cls;
    d.textContent = text;
    card.appendChild(d);
  });
  statsRow.appendChild(card);
});

