// Tour data is untrusted (Import loads a file someone else wrote, and the result is persisted): every stop is validated before use.
// Rule: integer tick 1..675, note = plain text of at most 280 characters with control characters removed, at most 100 stops.
function cleanStops(list) {
  const out = [];
  if (!Array.isArray(list)) return out;
  for (const s of list) {
    if (out.length >= 100) break;
    const tick = Number(s && s.tick);
    if (!Number.isInteger(tick) || tick < 1 || tick > 675) continue;
    const note = String(s.note == null ? '' : s.note).replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, 280);
    out.push({ tick, note });
  }
  return out;
}
